INSERT INTO "interview_responses" VALUES('76506655-1e4e-47cc-838a-3e41a0467eed','34c5cb10-2684-4c6b-a337-a793f3883b5b',0,'In a modern React application, what is the primary architectural benefit of utilizing server-state libraries like TanStack Query (React Query) over global Redux state?','technical','intermediate','Frontend Architecture','["React Query / SWR / Redux Toolkit", "memoization (useMemo/useCallback)", "cache invalidation", "optimistic updates"]','Option A: React Query eliminates the need for any CSS styling files',0.0,'{"score": 0.0, "is_correct": false, "selected_option": "A", "selected_text": "React Query eliminates the need for any CSS styling files", "correct_option": "B", "correct_text": "It natively manages asynchronous caching, background invalidation, request deduplication, and stale-while-revalidate lifecycles out of the box", "feedback": "\u2717 Incorrect. You selected Option A, but the correct answer is Option B. TanStack Query decouples server cache management (deduplication, polling, caching, error states) from client-only UI state, eliminating massive Redux boilerplate.", "explanation": "TanStack Query decouples server cache management (deduplication, polling, caching, error states) from client-only UI state, eliminating massive Redux boilerplate.", "strengths": [], "improvements": ["Review Frontend Architecture principles.", "Correct approach: Option B (It natively manages asynchronous caching, background invalidation, request deduplication, and stale-while-revalidate lifecycles out of the box)."]}','2026-09-23 15:24:40.560347');
CREATE TABLE interview_sessions (
            id TEXT PRIMARY KEY,
            candidate_id TEXT NOT NULL,
            job_id TEXT NOT NULL,
            interviewer_id TEXT,
            interview_type TEXT DEFAULT 'mixed',
            status TEXT DEFAULT 'in_progress',
            question_count INTEGER DEFAULT 5,
            current_question_index INTEGER DEFAULT 0,
            overall_score REAL DEFAULT 0.0,
            technical_score REAL DEFAULT 0.0,
            behavioral_score REAL DEFAULT 0.0,
            questions_json TEXT DEFAULT '[]',
            summary_report_json TEXT DEFAULT '{}',
            started_at DATETIME,
            completed_at DATETIME,
            created_at DATETIME,
            FOREIGN KEY (candidate_id) REFERENCES candidates (id),
            FOREIGN KEY (job_id) REFERENCES jobs (id),
            FOREIGN KEY (interviewer_id) REFERENCES users (id)
        );
