INSERT INTO "interview_sessions" VALUES('0b5cbee5-6297-4ca2-8b6a-d6b64db8e737','33037d2b-fe77-42f0-8bda-0268e60ec99f','a8686dab-3304-410f-9ec5-97f7e470e661','adad9899-1637-4338-98b7-463a68ffe1e2','technical','in_progress',5,1,0.0,0.0,0.0,'[{"question": "How do you architect state management and API caching in a modern React application to prevent unnecessary re-renders and stale data?", "type": "technical", "difficulty": "intermediate", "skill": "Frontend Architecture", "expected_focus": ["React Query / SWR / Redux Toolkit", "memoization (useMemo/useCallback)", "cache invalidation", "optimistic updates"], "number": 1, "skills": ["Frontend Architecture"], "expected_topics": ["React Query / SWR / Redux Toolkit", "memoization (useMemo/useCallback)", "cache invalidation", "optimistic updates"], "maximum_score": 10}, {"question": "Compare JSON Web Tokens (JWT) stored in HttpOnly cookies versus Authorization header Bearer tokens in terms of security trade-offs.", "type": "technical", "difficulty": "intermediate", "skill": "Authentication & Security", "expected_focus": ["XSS vs CSRF mitigation", "token expiration & refresh tokens", "SameSite attribute", "statelessness"], "number": 2, "skills": ["Authentication & Security"], "expected_topics": ["XSS vs CSRF mitigation", "token expiration & refresh tokens", "SameSite attribute", "statelessness"], "maximum_score": 10}, {"question": "When designing a REST or GraphQL API, how do you handle backward-compatible schema changes and database migrations with zero downtime?", "type": "technical", "difficulty": "advanced", "skill": "Backend Architecture & DB", "expected_focus": ["expand and contract pattern", "non-breaking field additions", "blue/green or rolling deploys", "deprecation cycles"], "number": 3, "skills": ["Backend Architecture & DB"], "expected_topics": ["expand and contract pattern", "non-breaking field additions", "blue/green or rolling deploys", "deprecation cycles"], "maximum_score": 10}, {"question": "How do you ensure cohesive communication and contract agreements when working across both frontend and backend boundaries in a team?", "type": "behavioral", "difficulty": "intermediate", "skill": "Collaboration & Standards", "expected_focus": ["OpenAPI / Swagger specs", "TypeScript shared types", "contract testing", "early mock endpoints"], "number": 4, "skills": ["Collaboration & Standards"], "expected_topics": ["OpenAPI / Swagger specs", "TypeScript shared types", "contract testing", "early mock endpoints"], "maximum_score": 10}, {"question": "Tell me about a complex full-stack feature where frontend performance was heavily constrained by database query speed, and how you resolved it.", "type": "situational", "difficulty": "intermediate", "skill": "End-to-End Problem Solving", "expected_focus": ["query profiling", "indexing & pagination", "server-side filtering vs client rendering", "perceived latency"], "number": 5, "skills": ["End-to-End Problem Solving"], "expected_topics": ["query profiling", "indexing & pagination", "server-side filtering vs client rendering", "perceived latency"], "maximum_score": 10}]','{"category_weights": {"technical": 0.5, "behavioral": 0.2, "situational": 0.2, "hr": 0.1}}','2026-09-23 14:50:54.632519',NULL,'2026-09-23 14:49:29.742628');
INSERT INTO "interview_sessions" VALUES('34c5cb10-2684-4c6b-a337-a793f3883b5b','33037d2b-fe77-42f0-8bda-0268e60ec99f','a8686dab-3304-410f-9ec5-97f7e470e661','adad9899-1637-4338-98b7-463a68ffe1e2','situational','in_progress',5,1,0.0,0.0,0.0,'[{"question": "In a modern React application, what is the primary architectural benefit of utilizing server-state libraries like TanStack Query (React Query) over global Redux state?", "options": {"A": "React Query eliminates the need for any CSS styling files", "B": "It natively manages asynchronous caching, background invalidation, request deduplication, and stale-while-revalidate lifecycles out of the box", "C": "React Query executes all component rendering on the backend Node.js server only", "D": "It replaces REST APIs with WebSockets automatically"}, "correct_option": "B", "explanation": "TanStack Query decouples server cache management (deduplication, polling, caching, error states) from client-only UI state, eliminating massive Redux boilerplate.", "type": "technical", "difficulty": "intermediate", "skill": "Frontend Architecture", "expected_focus": ["React Query / SWR / Redux Toolkit", "memoization (useMemo/useCallback)", "cache invalidation", "optimistic updates"], "number": 1, "skills": ["Frontend Architecture"], "expected_topics": ["React Query / SWR / Redux Toolkit", "memoization (useMemo/useCallback)", "cache invalidation", "optimistic updates"], "maximum_score": 10}, {"question": "When storing authentication tokens in web applications, why are HttpOnly, Secure, SameSite=Strict cookies generally considered safer than browser localStorage?", "options": {"A": "HttpOnly cookies are immune to Cross-Site Scripting (XSS) token extraction because JavaScript cannot read them", "B": "localStorage tokens expire automatically after 15 minutes", "C": "Cookies cannot be sent across HTTPS connections", "D": "localStorage does not support storing string values"}, "correct_option": "A", "explanation": "The HttpOnly flag blocks client-side scripts from reading the cookie, directly protecting the authentication token if an XSS vulnerability exists.", "type": "technical", "difficulty": "intermediate", "skill": "Authentication & Security", "expected_focus": ["XSS vs CSRF mitigation", "token expiration & refresh tokens", "SameSite attribute", "statelessness"], "number": 2, "skills": ["Authentication & Security"], "expected_topics": ["XSS vs CSRF mitigation", "token expiration & refresh tokens", "SameSite attribute", "statelessness"], "maximum_score": 10}, {"question": "When executing a zero-downtime database migration that involves renaming a production database column used by an active API, what pattern should you follow?", "options": {"A": "Run an immediate ALTER TABLE RENAME COLUMN query during peak hours", "B": "The Expand and Contract pattern: add new column, dual-write to both, backfill historical data, switch reads, and finally remove the old column", "C": "Take the database offline for 4 hours while running data scripts", "D": "Store all new values in an unstructured JSON column instead"}, "correct_option": "B", "explanation": "The Expand-and-Contract (Parallel Run) pattern ensures both old and new code versions run concurrently with zero downtime and safe rollback capabilities.", "type": "technical", "difficulty": "advanced", "skill": "Backend Architecture & DB", "expected_focus": ["expand and contract pattern", "non-breaking field additions", "blue/green or rolling deploys", "deprecation cycles"], "number": 3, "skills": ["Backend Architecture & DB"], "expected_topics": ["expand and contract pattern", "non-breaking field additions", "blue/green or rolling deploys", "deprecation cycles"], "maximum_score": 10}, {"question": "How do you establish seamless collaboration between frontend and backend developers working concurrently on an unreleased feature?", "options": {"A": "Have frontend developers wait until backend developers have completely finished and deployed code before starting", "B": "Define and agree upon an OpenAPI / TypeScript contract specification upfront and generate mock endpoints for client development", "C": "Allow each engineer to implement whatever property names they prefer and fix mismatches in production", "D": "Eliminate API contracts and pass all data as raw text blobs"}, "correct_option": "B", "explanation": "Contract-first development with OpenAPI / JSON Schema unblocks frontend work through automated mocks and shared types while backend builds the implementation.", "type": "behavioral", "difficulty": "intermediate", "skill": "Collaboration & Standards", "expected_focus": ["OpenAPI / Swagger specs", "TypeScript shared types", "contract testing", "early mock endpoints"], "number": 4, "skills": ["Collaboration & Standards"], "expected_topics": ["OpenAPI / Swagger specs", "TypeScript shared types", "contract testing", "early mock endpoints"], "maximum_score": 10}, {"question": "A frontend search input triggers a backend SQL query on every keystroke, resulting in severe database connection saturation. What is the immediate frontend remediation?", "options": {"A": "Increase backend server count to 100 instances", "B": "Debounce the input event (e.g. 300ms) and cancel stale in-flight HTTP requests using AbortController", "C": "Convert the input to a password field", "D": "Disable user search capabilities"}, "correct_option": "B", "explanation": "Debouncing postpones query execution until the user pauses typing, and AbortController terminates obsolete prior requests, protecting backend capacity.", "type": "situational", "difficulty": "intermediate", "skill": "End-to-End Problem Solving", "expected_focus": ["query profiling", "indexing & pagination", "server-side filtering vs client rendering", "perceived latency"], "number": 5, "skills": ["End-to-End Problem Solving"], "expected_topics": ["query profiling", "indexing & pagination", "server-side filtering vs client rendering", "perceived latency"], "maximum_score": 10}]','{"category_weights": {"technical": 0.5, "behavioral": 0.2, "situational": 0.2, "hr": 0.1}}','2026-09-23 15:21:53.261093',NULL,'2026-09-23 15:21:38.186127');
