        );
INSERT INTO "voice_screening_responses" VALUES('2365b8a0-a304-4745-a986-d1c1ab50c16b','voice-session-b99bb639',0,'Can you explain your experience building machine learning data pipelines and how you handle distributed training?','technical','PyTorch','I have built pipelines using PyTorch and Kubeflow where we shard data across multiple GPU workers. We used distributed data parallel with gradient accumulation to fit larger batch sizes.',45.0,86.0,'{"score": 86.0, "technical_accuracy": 87.0, "relevance": 88.0, "communication": 85.0, "completeness": 86.0, "role_knowledge": 87.0, "feedback": "Articulate explanation with clear references to production trade-offs.", "strengths": ["Clear technical articulation", "Solid grasp of PyTorch"], "improvements": ["Could mention specific benchmarking metrics."]}','2026-09-26 16:22:59.262840');
INSERT INTO "voice_screening_responses" VALUES('150ef424-5fe5-44d3-af3e-5b81d3e261fa','voice-session-b99bb639',1,'How do you monitor and handle model drift once deployed in a production service?','technical','MLOps','We track prediction latency, confidence distribution, and ground truth feedback. When Jensen-Shannon divergence exceeds 0.15, an automated retraining alert is triggered.',45.0,85.0,'{"score": 85.0, "technical_accuracy": 86.0, "relevance": 87.0, "communication": 84.0, "completeness": 85.0, "role_knowledge": 86.0, "feedback": "Articulate explanation with clear references to production trade-offs.", "strengths": ["Clear technical articulation", "Solid grasp of MLOps"], "improvements": ["Could mention specific benchmarking metrics."]}','2026-09-26 16:22:59.262840');
INSERT INTO "voice_screening_responses" VALUES('2cd05cd1-32b5-4796-92df-f16faf11ba7f','voice-session-b99bb639',2,'What is your approach to optimizing inference speed for LLM endpoints?','technical','Model Optimization','We evaluate KV caching, dynamic tensor batching, and int8 or fp8 quantization with vLLM to maximize throughput per GPU.',45.0,82.0,'{"score": 82.0, "technical_accuracy": 83.0, "relevance": 84.0, "communication": 81.0, "completeness": 82.0, "role_knowledge": 83.0, "feedback": "Articulate explanation with clear references to production trade-offs.", "strengths": ["Clear technical articulation", "Solid grasp of Model Optimization"], "improvements": ["Could mention specific benchmarking metrics."]}','2026-09-26 16:22:59.262840');
